const used = new Set<string>();

/**
 * Whether `actual` is the ported output of a golden case whose golden `expected` predates it. A case that now
 * matches the golden needs no entry; one that differs must have an entry with exactly `actual`.
 */
export const aheadOfFixture = (key: string, actual: string, expected: string): boolean => {
  if (actual === expected) return true;
  const entry = PORTED_AHEAD_OF_FIXTURES.get(key);

  if (entry === undefined || entry.out !== actual) return false;
  used.add(key);

  return true;
};

/** The entries no case used: stale once the ported behaviour or the fixtures change. */
export const unusedAheadOfFixtureEntries = (): string[] =>
  [...PORTED_AHEAD_OF_FIXTURES.keys()].filter((key) => !used.has(key));
